package migration

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"

	"github.com/vantt/mcp-skill-hub/internal/mutation"
)

func migrateSkillYAMLToV3(root string) ([]mutation.Change, []FileDiff, error) {
	var changes []mutation.Change
	var diffs []FileDiff

	skillsDir := filepath.Join(root, "skills")
	err := filepath.WalkDir(skillsDir, func(path string, d os.DirEntry, err error) error {
		if err != nil { … }
		if d.IsDir() || d.Name() != "skill.meta.yaml" {
			return nil
		}

		relPath, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}

		contents, err := os.ReadFile(path)
		if err != nil {
			return err
		}

		var doc yaml.Node
		if err := yaml.Unmarshal(contents, &doc); err != nil {
			return fmt.Errorf("parse %s: %w", relPath, err)
		}

		// Transform the YAML structure.
		if doc.Kind == yaml.DocumentNode && len(doc.Content) > 0 && doc.Content[0].Kind == yaml.MappingNode { … }

		var out bytes.Buffer
		encoder := yaml.NewEncoder(&out)
		encoder.SetIndent(2)
		if err := encoder.Encode(&doc); err != nil {
			return err
		}
		encoder.Close()

		newContents := out.Bytes()
		newRelPath := filepath.Join(filepath.Dir(relPath), ".meta", "skill.yaml")

		changes = append(changes,
			mutation.Change{Path: relPath, Contents: nil},            // delete old
			mutation.Change{Path: newRelPath, Contents: newContents}, // create new
		)

		diffs = append(diffs,
			FileDiff{Path: relPath, Before: string(contents), After: "", Diff: fmt.Sprintf("- deleted %s\n", relPath)},
			FileDiff{Path: newRelPath, Before: "", After: string(newContents), Diff: fmt.Sprintf("+ created %s\n", newRelPath)},
		)
		return nil
	})

	return changes, diffs, err
}

