// Transform the YAML structure.
if doc.Kind == yaml.DocumentNode && len(doc.Content) > 0 && doc.Content[0].Kind == yaml.MappingNode {
	mapping := doc.Content[0]
	var newContent []*yaml.Node
	var routingNode *yaml.Node
	var provenanceNode *yaml.Node

	// Extract nodes
	for i := 0; i < len(mapping.Content); i += 2 {
		key := mapping.Content[i].Value
		val := mapping.Content[i+1]

		switch key {
		case "name", "description", "collection", "collection_id", "history", "created_at", "updated_at", "quality", "content":
			// drop
		case "schema_version":
			val.Value = "2"
			newContent = append(newContent, mapping.Content[i], val)
		case "aliases", "domain", "topics", "technologies":
			// move to routing
			if routingNode == nil {
				routingNode = &yaml.Node{Kind: yaml.MappingNode}
			}
			routingNode.Content = append(routingNode.Content, mapping.Content[i], val)
		case "routing":
			if routingNode == nil {
				routingNode = &yaml.Node{Kind: yaml.MappingNode}
			}
			routingNode.Content = append(routingNode.Content, val.Content...)
		case "provenance":
			provenanceNode = val
		default:
			newContent = append(newContent, mapping.Content[i], val)
		}
	}

	if routingNode != nil && len(routingNode.Content) > 0 {
		newContent = append(newContent, &yaml.Node{Kind: yaml.ScalarNode, Value: "routing"}, routingNode)
	}

	if provenanceNode != nil {
		// Convert provenance to sources
		sourcesNode := &yaml.Node{Kind: yaml.SequenceNode}
		sourceItem := &yaml.Node{Kind: yaml.MappingNode}

		for i := 0; i < len(provenanceNode.Content); i += 2 {
			k := provenanceNode.Content[i].Value
			v := provenanceNode.Content[i+1]
			if k == "origin" {
				for j := 0; j < len(v.Content); j += 2 {
					sourceItem.Content = append(sourceItem.Content, v.Content[j], v.Content[j+1])
				}
			} else {
				sourceItem.Content = append(sourceItem.Content, provenanceNode.Content[i], v)
			}
		}
		sourceItem.Content = append(sourceItem.Content,
			&yaml.Node{Kind: yaml.ScalarNode, Value: "roles"},
			&yaml.Node{Kind: yaml.SequenceNode, Content: []*yaml.Node{{Kind: yaml.ScalarNode, Value: "upstream"}}},
		)
		sourcesNode.Content = append(sourcesNode.Content, sourceItem)
		newContent = append(newContent, &yaml.Node{Kind: yaml.ScalarNode, Value: "sources"}, sourcesNode)
	}

	mapping.Content = newContent
}

var out bytes.Buffer
encoder := yaml.NewEncoder(&out)
encoder.SetIndent(2)
if err := encoder.Encode(&doc); err != nil {
	return err
}
encoder.Close()

