320:func validateSkillEntrypoint(path, absolute, skillID string) []Issue {
321:	var issues []Issue
322:	info, err := os.Lstat(absolute)
323:	if err != nil {
324:		return []Issue{{Path: path, Message: err.Error()}}
325:	}
326:	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
327:		return []Issue{{Path: path, Message: "skill entrypoint must be a regular file"}}
328:	}
329:	if info.Size() == 0 {
330:		return []Issue{{Path: path, Message: "skill resource must not be empty"}}
331:	}
332:	if info.Size() > maxSkillResourceBytes {
333:		return []Issue{{Path: path, Message: fmt.Sprintf("skill resource exceeds %d bytes", maxSkillResourceBytes)}}
334:	}
335:	contents, err := os.ReadFile(absolute)
336:	if err != nil {
337:		return []Issue{{Path: path, Message: err.Error()}}
338:	}
339:	if !utf8.Valid(contents) {
340:		return []Issue{{Path: path, Message: "text skill resource must be valid UTF-8"}}
341:	}
342:	if fmName, line, ok := parseFrontmatterName(contents); ok && fmName != "" && fmName != skillID {
343:		issues = append(issues, Issue{
