			add("routing.requirements " + err.Error())
		}
	}
	for _, field := range []string{"distinguish_from", "supporting", "equivalent_to"} {
		targets, err := relationshipTargets(routingValues[field], field)
		if err != nil {
			add("routing." + field + " " + err.Error())
		} else {
