79:	if len(commits) > historyLimit {
80:		changes.HistoryTruncated = true
81:		commits = commits[:historyLimit]
82:	}
83:	approvalCommit, approvedMeta := "", []byte(nil)
84:	runEndedInHistory := false
85:	for _, commit := range commits {
86:		meta, err := gitOutput(ctx, root, "show", commit+":./"+metaPath)
87:		var past contentTrustDocument
88:		matches := err == nil && yaml.Unmarshal(meta, &past) == nil && past.Quality.ContentReviewedDigest == approved
89:		if matches {
90:			approvalCommit, approvedMeta = commit, meta
91:			continue
92:		}
93:		if approvalCommit != "" {
94:			runEndedInHistory = true
95:			break
96:		}
97:	}
98:	// A run that reaches the end of a truncated walk may continue further back,
99:	// so its oldest visible commit is not known to be the approval.
100:	if approvalCommit == "" || (changes.HistoryTruncated && !runEndedInHistory) {
101:		return changes
102:	}
103:	approvedFiles, ok := gitTreeBlobs(ctx, root, approvalCommit, skillRelDir)
104:	if !ok {
105:		return changes
106:	}
107:	currentFiles, ok := currentBlobs(ctx, root, skillRelDir, resources)
108:	if !ok {
109:		return changes
110:	}
111:	changes.Found = true
112:	changes.Commit = approvalCommit
113:	changes.DiffCommand = fmt.Sprintf("git diff %s -- %s", approvalCommit[:12], skillRelDir)
114:	for name, blob := range currentFiles {
115:		switch before, existed := approvedFiles[name]; {
116:		case !existed:
117:			changes.Added = append(changes.Added, name)
118:		case before != blob:
119:			changes.Modified = append(changes.Modified, name)
