// Package migration plans explicit, ordered canonical schema migrations.
package migration

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/vantt/mcp-skill-hub/internal/canonical"
