	skillChanges, skillDiffs, err := migrateSkillYAMLToV3(root)
	if err != nil {
		return nil, nil, err
	}
	changes = append(changes, skillChanges...)
	diffs = append(diffs, skillDiffs...)
	return changes, diffs, nil
}

