	quality := make(map[string]any)
	if existingMap != nil {
		if q, ok := existingMap["quality"].(map[string]any); ok {
			for k, v := range q {
				quality[k] = v
			}
		}
	}
	if q, ok := oldMap["quality"].(map[string]any); ok {
		for k, v := range q {
			quality[k] = v
		}
	}
	// drop curated from quality if present
	delete(quality, "curated")
	if len(quality) > 0 {
		merged["quality"] = quality
	}

	// Sources: convert old provenance to upstream source, and merge with existing sources
	var sources []any
	if existingMap != nil {
		if srcs, ok := existingMap["sources"].([]any); ok {
			sources = append(sources, srcs...)
		}
	}

	if prov, ok := oldMap["provenance"].(map[string]any); ok && prov != nil {
		sourceID, _ := prov["source_id"].(string)
		origin, _ := prov["origin"].(map[string]any)
		if origin != nil || sourceID != "" {
			upstreamSrc := make(map[string]any)
			srcID := sourceID
			if srcID == "" {
				if n, ok := origin["name"].(string); ok && n != "" {
					srcID = n
				} else {
					srcID = oldID
				}
			}
			upstreamSrc["id"] = srcID
			upstreamSrc["roles"] = []string{"upstream"}
			if origin != nil {
				for k, v := range origin {
					if k != "added_at" && k != "content_digest" {
						upstreamSrc[k] = v
					}
				}
				if c, ok := origin["commit"].(string); ok && c != "" {
					upstreamSrc["synced"] = c
				}
			}
			upstreamSrc["roles"] = []string{"upstream"}

			// Check if upstream source already exists in sources
			foundUpstream := false
			for i, s := range sources {
				if sMap, ok := s.(map[string]any); ok {
					roles, _ := sMap["roles"].([]any)
					hasUpstream := false
					for _, r := range roles {
						if r == "upstream" {
							hasUpstream = true
							break
						}
					}
					if hasUpstream {
						foundUpstream = true
						// Merge fields
						for k, v := range upstreamSrc {
							if k == "synced" && sMap["synced"] != nil {
								continue // preserve existing synced cursor
							}
							sMap[k] = v
						}
						sources[i] = sMap
						break
					}
				}
			}
			if !foundUpstream {
				sources = append([]any{upstreamSrc}, sources...)
			}
		}
	}

	if len(sources) > 0 {
		merged["sources"] = sources
	}

	var buf bytes.Buffer
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(merged); err != nil {
		return nil, err
	}
	_ = enc.Close()

	return buf.Bytes(), nil
}

