func extractSkillMDNameAndDesc(contents []byte, defaultID string) (string, string) {
	name, desc := "", ""
	lines := strings.Split(string(contents), "\n")
	bodyStart := 0
	if len(lines) > 0 && strings.TrimSpace(lines[0]) == "---" {
		for i := 1; i < len(lines); i++ {
			trimmed := strings.TrimSpace(lines[i])
			if trimmed == "---" {
				bodyStart = i + 1
				break
			}
			if strings.HasPrefix(trimmed, "name:") {
				name = strings.Trim(strings.TrimSpace(strings.TrimPrefix(trimmed, "name:")), `"'`)
			}
			if strings.HasPrefix(trimmed, "description:") {
				desc = strings.Trim(strings.TrimSpace(strings.TrimPrefix(trimmed, "description:")), `"'`)
			}
		}
	}
	bodyLines := lines[bodyStart:]
	for _, line := range bodyLines {
		trimmed := strings.TrimSpace(line)
		if name == "" && strings.HasPrefix(trimmed, "# ") {
			name = strings.TrimSpace(strings.TrimPrefix(trimmed, "# "))
		} else if desc == "" && trimmed != "" && !strings.HasPrefix(trimmed, "#") {
			desc = trimmed
		}
		if name != "" && desc != "" {
			break
		}
	}
	if name == "" {
		name = defaultID
	}
	if desc == "" {
		desc = name
	}
	return name, desc
}

func jsonMarshalStable(value any) ([]byte, error) {
	// encoding/json sorts string map keys, giving logical rows stable serialization.
	return json.Marshal(value)
}

