		t.Fatalf("unsupported platform exit = %d:\n%s", code, stdout)
	}
	if strings.Contains(stdout, "check-ran") || strings.Contains(stdout, "setup_check") {
		t.Fatalf("setup check ran on an unsupported platform:\n%s", stdout)
	}
}

