		t.Fatal(err)
	}
	skillContent := "---\nname: pdf-tools\ndescription: Extract and convert PDF files.\n---\n\n# PDF Tools\n\nInstructions.\n"
	if err := os.WriteFile(filepath.Join(sourceDir, "SKILL.md"), []byte(skillContent), 0o600); err != nil {
