	if draftGet.LifecycleState != "draft" {
		t.Fatalf("expected draft state, got %s", draftGet.LifecycleState)
	}

	// 4. Blocked loads: unapproved third-party skill
	setSkillMeta(t, root, func(doc map[string]any) {
		doc["sources"] = []any{
