		t.Fatalf("markdown-to-epub must be local in v1: %+v", beforeSnapshots["markdown-to-epub"])
	}
	if beforeSnapshots["markdown-to-epub"].Name != "Markdown to Epub" {
		t.Fatalf("markdown-to-epub name in v1 = %q, want %q", beforeSnapshots["markdown-to-epub"].Name, "Markdown to Epub")
	}
	// herdr-cook-plan is third-party (from herdr-cook-plan.git)
	if !beforeSnapshots["herdr-cook-plan"].ThirdParty {
		t.Fatalf("herdr-cook-plan must be third-party in v1: %+v", beforeSnapshots["herdr-cook-plan"])
	}

	// Step 1: Migrate v1 -> v2
	proposalV2, err := migration.DefaultRegistry().Preview(root, 2)
	if err != nil {
		t.Fatalf("preview migration v1->v2: %v", err)
	}
	receiptV2, err := mutation.ConfirmMutation(root, proposalV2.Mutation, mutation.Confirmation{
		ProposalID:          proposalV2.ID,
		ProposalDigest:      proposalV2.Digest,
		BaseCatalogSnapshot: proposalV2.BaseSnapshot,
	})
	if err != nil {
		t.Fatalf("confirm migration v1->v2: %v", err)
	}
	if receiptV2.OperationID == "" {
		t.Fatal("empty receipt operation ID for v1->v2")
	}
	v2Version, err := migration.DetectVersion(root)
	if err != nil || v2Version != 2 {
		t.Fatalf("expected version 2 after v1->v2, got %d (err: %v)", v2Version, err)
	}

	// Step 2: Migrate v2 -> v3
	proposalV3, err := migration.DefaultRegistry().Preview(root, 3)
	if err != nil {
		t.Fatalf("preview migration v2->v3: %v", err)
	}
	receiptV3, err := mutation.ConfirmMutation(root, proposalV3.Mutation, mutation.Confirmation{
		ProposalID:          proposalV3.ID,
		ProposalDigest:      proposalV3.Digest,
		BaseCatalogSnapshot: proposalV3.BaseSnapshot,
	})
	if err != nil {
		t.Fatalf("confirm migration v2->v3: %v", err)
