		}
		up, _ := service.GetSkillUpstream(ctx, root, id)
		afterSnapshot := skillFactSnapshot{
			ThirdParty:     review.ContentTrust.ThirdParty,
			Approved:       review.ContentTrust.Approved,
			RequiresReview: review.ContentTrust.RequiresReview(),
