			t.Errorf("skill %s: Name changed from %q to %q", id, before.Name, afterSnapshot.Name)
		}
	}

	// Verify test-audit merged .meta/skill.yaml
	testAuditMetaPath := filepath.Join(root, "skills", "default", "test-audit", ".meta", "skill.yaml")
