		t.Fatal("empty receipt operation ID for v1->v3")
	}
	v3Version, err := migration.DetectVersion(root)
	if err != nil || v3Version != 3 {
		t.Fatalf("expected version 3 after v1->v3, got %d (err: %v)", v3Version, err)
	}

