}

func mergeSources(oldMap, existingMap map[string]any, defaultID string) []any {
	var sources []any
	if existingMap != nil {
		if srcs, ok := existingMap["sources"].([]any); ok {
			for _, s := range srcs {
				if sMap, ok := s.(map[string]any); ok {
					cloned := make(map[string]any, len(sMap)+2)
					for k, v := range sMap {
