		t.Fatalf("contract version = %q, want %q", metadata.ContractVersion, CuratorContractVersion)
	}
	if metadata.ActivationPolicy != "explicit-only" {
		t.Fatalf("activation policy = %q, want explicit-only", metadata.ActivationPolicy)
	}
