+	skillDir := filepath.Join(repoDir, "skills", "remote-skill")
+	if err := os.MkdirAll(skillDir, 0o700); err != nil {
+		t.Fatal(err)
+	}
+	content := "---\nname: remote-skill\ndescription: Remote skill description\n---\n# Remote Skill\n\nContent.\n"
