137:// ApplyLesson updates or appends a lesson, implementing D7 reopening logic:
138:// If the lesson already has a decision (planned, ported, rejected) and the updated Where entries
139:// include any new evidence not seen when the decision was recorded (in Decision.SeenWhere),
140:// the decision status is automatically reset to "candidate".
141:func (doc *Document) ApplyLesson(incoming Lesson, now time.Time) error {
142:	if err := ValidateLesson(&incoming); err != nil {
143:		return err
144:	}
145:	foundIdx := -1
146:	for i, l := range doc.Lessons {
147:		if l.Key == incoming.Key {
148:			foundIdx = i
149:			break
150:		}
151:	}
152:
153:	if foundIdx < 0 {
154:		// New lesson
155:		if incoming.Decision.Status == "" {
156:			incoming.Decision.Status = "candidate"
157:		}
158:		if incoming.Decision.At == "" {
159:			incoming.Decision.At = now.UTC().Format(time.RFC3339)
160:		}
161:		doc.Lessons = append(doc.Lessons, incoming)
162:		return nil
163:	}
164:	existing := doc.Lessons[foundIdx]
165:	// Union where entries
166:	mergedWhere := append([]string{}, existing.Where...)
167:	for _, w := range incoming.Where {
168:		if !slices.Contains(mergedWhere, w) {
169:			mergedWhere = append(mergedWhere, w)
170:		}
171:	}
172:	slices.Sort(mergedWhere)
173:
174:	// Check if any evidence in mergedWhere was not in existing.Decision.SeenWhere
175:	hasNewEvidence := false
176:	if existing.Decision.Status != "" && existing.Decision.Status != "candidate" {
177:		seenMap := make(map[string]bool, len(existing.Decision.SeenWhere))
178:		for _, w := range existing.Decision.SeenWhere {
179:			seenMap[w] = true
180:		}
181:		for _, w := range mergedWhere {
182:			if !seenMap[w] {
183:				hasNewEvidence = true
184:				break
185:			}
186:		}
187:	}
188:
189:	existing.What = incoming.What
190:	existing.Notable = incoming.Notable
191:	if incoming.Contrast != "" {
192:		existing.Contrast = incoming.Contrast
193:	}
194:	if incoming.Scores != nil {
195:		existing.Scores = incoming.Scores
196:	}
197:	existing.Where = mergedWhere
198:
199:	if hasNewEvidence {
200:		// D7: A new where entry reopens a decided lesson
201:		existing.Decision.Status = "candidate"
202:		existing.Decision.Reason = fmt.Sprintf("reopened: new evidence observed (%d sources)", len(mergedWhere))
203:		existing.Decision.At = now.UTC().Format(time.RFC3339)
204:		// Keep existing SeenWhere so human knows what was previously evaluated
205:	} else if incoming.Decision.Status != "" && incoming.Decision.Status != existing.Decision.Status {
206:		// Explicit new decision
207:		existing.Decision.Status = incoming.Decision.Status
208:		existing.Decision.Reason = incoming.Decision.Reason
209:		existing.Decision.At = now.UTC().Format(time.RFC3339)
210:		existing.Decision.SeenWhere = append([]string{}, mergedWhere...)
211:	}
212:
213:	doc.Lessons[foundIdx] = existing
214:	return nil
215:}
