	candLesson, ok := lessonMap["mocks-mirror-the-real-shape"]
	if !ok || candLesson.Decision.Status != "candidate" {
		t.Fatalf("expected candidate lesson for mocks-mirror-the-real-shape, got %#v", candLesson)
	}

