	_ = os.MkdirAll(filepath.Join(root, "sources", "skills"), 0o755)
	_ = os.WriteFile(filepath.Join(root, "sources", "skills", "LINK-sample-skill--src-1.yaml"), []byte("skill_id: sample-skill\nsource_id: src-1\n"), 0o644)

