	resultSnapshot, err := validateVirtualSnapshot(root, virtualChanges)
	if err != nil {
		return Receipt{}, err
	}
	return commitPrepared(root, set, changes, resultSnapshot.CatalogSnapshot, occurredAt, options)
}

