			}
		case strings.Contains(slash, "/incorporations/"):
			var item insightpkg.Incorporation
			item, err = insightpkg.ParseIncorporation(data)
			if err == nil {
				incorporations[item.ID] = item
			}
		}
		return err
	}); err != nil {
		return err
	}

