			_, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(pin.Path)))
			if pin.After == "" {
				if !errors.Is(err, os.ErrNotExist) {
					return fmt.Errorf("proposal %s deleted path %s still exists", proposal.ID, pin.Path)
				}
