package mcpserver

import (
	"context"
	"fmt"
	"strings"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/vantt/mcp-skill-hub/internal/app"
)

type sourceListInput struct {
	Status string `json:"status,omitempty"`
}

type sourceCheckInput struct {
	SourceIDs []string `json:"source_ids,omitempty"`
	AllDue    bool     `json:"all_due,omitempty"`
}

func (adapter *Server) registerSourceTools(server *mcp.Server) {
	addTool(server, &mcp.Tool{
		Name:        "source_list",
		Title:       "List sources",
		Description: "List monitored sources in the catalog. Pass optional status filter (watching, error, disabled).",
		Annotations: annotations(true, false, false, false),
	}, func(ctx context.Context, _ *mcp.CallToolRequest, input sourceListInput) (*mcp.CallToolResult, toolOutcome[app.SourceListResult], error) {
		return appResult(adapter.source.ListSources(ctx, adapter.workspace, strings.TrimSpace(input.Status)))
	})

	addTool(server, &mcp.Tool{
		Name:        "source_check",
		Title:       "Check sources",
		Description: "Check selected or due source revisions through configured adapters. This records revision changes and per-skill upstream results in results[].skills without editing curated skills.",
		Annotations: annotations(false, false, false, true),
	}, func(ctx context.Context, _ *mcp.CallToolRequest, input sourceCheckInput) (*mcp.CallToolResult, toolOutcome[app.SourceCheckResult], error) {
		if len(input.SourceIDs) == 0 && !input.AllDue {
			return failure[app.SourceCheckResult](fmt.Errorf("source_ids or all_due=true is required"))
		}
		return appResult(adapter.source.CheckSources(ctx, adapter.workspace, input.SourceIDs, input.AllDue))
	})
}

package mcpserver

import (
	"context"
	"strings"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/vantt/mcp-skill-hub/internal/app"
	resolverpkg "github.com/vantt/mcp-skill-hub/internal/resolver"
	"github.com/vantt/mcp-skill-hub/internal/skill"
)

func (adapter *Server) registerInsightTools(server *mcp.Server) {
	addTool(server, &mcp.Tool{
		Name:        "skill_update_preview",
		Title:       "Preview skill update",
		Description: "Persist a validated skill update preview and return exact confirmation pins. No canonical skill files change during preview. runtime replaces the skill's runtime block (requires.bins/env/platforms, setup.check/command; an empty object removes it); changing it requires the user to review the skill again before its files are served to agents.",
		Annotations: annotations(false, false, false, false),
	},
		func(ctx context.Context, _ *mcp.CallToolRequest, input skillUpdatePreviewInput) (*mcp.CallToolResult, toolOutcome[app.SkillProposal], error) {
			update := skill.UpdateInput{
				IdempotencyKey:        input.IdempotencyKey,
				Name:                  input.Name,
				Description:           input.Description,
				ExpectedContentDigest: strings.TrimSpace(input.ExpectedContentDigest),
				Routing:               input.Routing,
				Rationale:             input.Rationale,
				Runtime:               input.Runtime,
			}
			if input.Content != nil {
				update.SetContent = true
				update.Content = []byte(*input.Content)
			}
			if len(input.RemoveFiles) > 0 {
				update.RemoveFiles = append([]string(nil), input.RemoveFiles...)
			}
			if len(input.AddFiles) > 0 {
				update.AddFiles = make(map[string][]byte, len(input.AddFiles))
				for path, content := range input.AddFiles {
					update.AddFiles[path] = []byte(content)
				}
			}
			proposal, err := adapter.skillEdit.PreviewUpdate(ctx, adapter.workspace, strings.TrimSpace(input.SkillID), update)
			if err != nil {
				return failure[app.SkillProposal](err)
			}
			return success(proposal)
		})

	addTool(server, &mcp.Tool{
		Name:        "skill_update_confirm",
		Title:       "Confirm skill update",
		Description: "Apply exactly one persisted skill proposal. All proposal_id, proposal_digest, and base_version pins are required and exact replay returns the prior receipt.",
		Annotations: annotations(false, true, true, false),
	},
		func(ctx context.Context, _ *mcp.CallToolRequest, input confirmationInput) (*mcp.CallToolResult, toolOutcome[app.SkillMutationResult], error) {
			if strings.TrimSpace(input.ProposalID) == "" || strings.TrimSpace(input.ProposalDigest) == "" || strings.TrimSpace(input.BaseVersion) == "" {
				return failure[app.SkillMutationResult](app.NewInvalidRequestError("proposal_id, proposal_digest, and base_version pins are required", "Supply all confirmation pins."))
			}
			result, err := adapter.skillEdit.ConfirmUpdate(ctx, adapter.workspace, input.ProposalID, input.ProposalDigest, input.BaseVersion)
			if err != nil {
				return failure[app.SkillMutationResult](err)
			}
			return success(result)
		})

	addTool(server, &mcp.Tool{
		Name:        "routing_evaluate",
		Title:       "Evaluate routing",
		Description: "Evaluate one versioned request with the same deterministic resolver, catalog snapshot, policy revision, and distribution pins used by skill_resolve. This read-only evaluation never changes policy.",
		Annotations: annotations(true, false, true, false),
	},
		func(ctx context.Context, _ *mcp.CallToolRequest, input resolveInput) (*mcp.CallToolResult, toolOutcome[routingEvaluationResult], error) {
			resolved, err := adapter.resolver.EvaluateRouting(ctx, adapter.workspace, resolverpkg.ResolveRequest{
				Task:          input.Task,
				Context:       input.Context,
				Runtime:       input.Runtime,
				Prior:         input.Prior,
				Clarification: input.Clarification,
			})
			if err != nil {
				return failure[routingEvaluationResult](err)
			}
			return success(routingEvaluationResult{ResolveResponse: resolved})
		})
}

