func TestSourceWatchPreviewRejectsLocalFolders(t *testing.T) {
	t.Parallel()
	root := newEmptyMCPWorkspace(t)
	session := connectInMemoryServer(t, root)

	localCases := []string{
		"./sources/local",
		"../sources/local",
		filepath.Join(root, "sources"),
		"~/sources/repo",
		"sources-local",
