		if what == "" {
			what = strings.TrimSpace(ins.Rationale)
		}
		notable := strings.TrimSpace(ins.Rationale)
		if notable == "" {
			notable = what
		}
		where := []string{fmt.Sprintf("usage:%s", strings.ToLower(ins.ID))}

