	ver, err := DetectVersion(root)
	if err != nil || ver != 3 {
		t.Fatalf("workspace version changed: ver=%d, err=%v", ver, err)
	}
	if _, err := os.Stat(filepath.Join(skillDir, ".meta", "distill.yaml")); !os.IsNotExist(err) {
