						}
					}
				}
				hasUpstream := false
				for _, r := range roles {
					if r == "upstream" {
						hasUpstream = true
						break
					}
				}
				if !hasUpstream {
					roles = append([]string{"upstream"}, roles...)
				}
				sMap["roles"] = roles

				for k, v := range upstreamSrc {
					if k == "roles" || k == "learn_paths" || k == "repository" {
