func deriveLocalStatus(originFilesDigest, currentLocalDigest string) string {
	if originFilesDigest == "" {
		return "unknown"
	}
	if originFilesDigest == currentLocalDigest {
		return "clean"
	}
	return "modified"
}

func deriveNextAction(status, skillID, sha string) string {
	switch status {
	case "up_to_date":
		return "Up to date with upstream."
	case "update_available":
		return fmt.Sprintf("Run skillhub upstream review %s to inspect and apply changes.", skillID)
	case "modified":
		return fmt.Sprintf("Local edits differ from upstream base. Run skillhub upstream review %s to inspect drift.", skillID)
	case "diverged":
		return fmt.Sprintf("Both local and upstream changed. Run skillhub upstream review %s to 3-way merge.", skillID)
	case "upstream_removed":
		return "Skill removed in upstream repository. Decide whether to retain as custom skill."
	case "unavailable":
		return "Upstream repository could not be reached. Check network or repository access."
	case "untracked":
		return "Not linked to an upstream source. Run skillhub source attach to track updates."
	case "pinned":
		return fmt.Sprintf("Upstream tracking pinned to commit %s. Run skillhub source attach --ref <branch> to follow a branch.", sha)
	default:
		return ""
	}
}

func deriveUpstreamStatus(
	origin SkillOrigin,
	sourceID string,
	sourceRec *sourcepkg.Record,
	state *sourcepkg.UpstreamState,
	currentLocalDigest string,
) (status string, local string, errStr string) {
	local = deriveLocalStatus(origin.FilesDigest, currentLocalDigest)

	if (origin.Kind == "github" || origin.Kind == "git") && sourceID == "" {
		return "untracked", local, ""
	}

	if is40Hex(origin.Ref) {
		return "pinned", local, ""
	}

	if sourceRec == nil || !sameRepository(sourceRec.Locator.Repository, origin.Repository) || sourceRec.Locator.Ref != origin.Ref {
		return "unavailable", local, "source_origin_mismatch"
	}

	if state == nil || state.BaseCommit != origin.Commit || !sameRepository(state.Repository, origin.Repository) || state.Ref != origin.Ref || state.Path != origin.Path {
		return "unknown", local, ""
	}

	if state.Upstream == "unavailable" {
		return "unavailable", local, state.LastError
	}
…
	return "unknown", local, ""
}

