	if origin != nil {
		for k, v := range origin {
			if k != "added_at" && k != "content_digest" && k != "name" && k != "repository" {
				upstreamSrc[k] = v
			}
		}
		if c, ok := origin["commit"].(string); ok && c != "" {
			upstreamSrc["synced"] = c
		}
	}

