		}
	}
	if upstreamRepo != "" {
		upstreamSrc["repo"] = upstreamRepo
	}
	delete(upstreamSrc, "repository") // Write exactly one key, repo (D2)

	foundUpstream := false
	for i, s := range sources {
		if sMap, ok := s.(map[string]any); ok {
			existingRepo := ""
			if r, ok := sMap["repo"].(string); ok && r != "" {
