			ApplicationCommand: "source_watch_confirm",
			Confirmation: ConfirmationRequirement{
				Required: true,
				Mode:     "preview-and-approval",
				Pins:     pins,
			},
		},
		planned:   planned,
		expiresAt: expiresAt,
	}

	if err := storeSourceProposal(root, proposal, service.Clock.Now().UTC()); err != nil {
		return SourceProposal{}, err
	}
	return proposal, nil
}

