    const confirmBtn = screen.getByText('Confirm update');
    expect(confirmBtn).not.toBeDisabled();
    fireEvent.click(confirmBtn);

    await waitFor(() => {
      expect(confirmSpy).toHaveBeenCalledWith('PROP-CLEAN', {
