  | { type: 'command'; command: string; label: string }
  | { type: 'link'; to: string; label: string; note?: string }
  | { type: 'none' };

export interface ActionInput {
  kind: string;
  id?: string;
  count?: number;
  command?: string;
  label?: string;
  summary?: string;
}

export function resolveActionCta(action?: ActionInput): CtaResult {
  if (!action) {
    return { type: 'none' };
  }

  switch (action.kind) {
    case 'repair_workspace':
