			Score: distill.Score{
				Relevance: 3,
				Facts:     []string{"a", "b", "c"},
				Impact:    3,
				Evidence:  2,
				Effort:    1,
				Why:       "Migrated from legacy insight",
			},
			Decision: distill.Decision{
				State:  state,
				Reason: reason,
				At:     time.Now().UTC().Format(time.RFC3339),
			},
		}
