    const confirmBtn = unlinkButtons[unlinkButtons.length - 1];
    if (!confirmBtn) throw new Error('confirm button not found');
    fireEvent.click(confirmBtn);

    await waitFor(() => {
      expect(detachSpy).toHaveBeenCalledWith('test-skill', 'src-docs');
