                    className="fg-btn fg-btn--ghost"
                    onClick={() => refetchHome()}
                  >
                    <span>{t('action.reload')}</span>
                  </button>
                </>
              }
            >
              <strong>
                <span>{t('home.degraded_title')}</span>
              </strong>{' '}
              <span>{t('home.degraded_body')}</span>
            </Banner>
          )}

          {expired ? <SessionExpired /> : children}
        </main>
      </div>
    </div>
  );
}

