import { useQuery } from '@tanstack/react-query';
import { apiFetch } from './client';
import type {
  ConfirmationPins,
  CurationHome,
  DistillRunResult,
  FunnelReport,
  FunnelSince,
  InboxPageResult,
  InsightApplicationPreview,
  InsightApplicationResult,
  InsightDecisionResult,
  InsightDetailResult,
  SessionResponse,
  SkillAddProposal,
  SkillAddResult,
  SkillDetail,
  SkillListResult,
  SkillMutationResult,
  SkillProposal,
  SkillReviewResult,
  SkillRuntimeStatus,
  SkillSourcesResult,
  SkillDistillDocument,
  SkillUpstream,
  SourceCheckResult,
  SourceImportProposal,
  SourceListResult,
  SourceMutationResult,
  SourceProposal,
  UpstreamUpdatePreview,
  UpstreamUpdateResult,
} from './types';

export function useSession() {
  return useQuery({
    queryKey: ['session'],
    queryFn: () => apiFetch<SessionResponse>('/session'),
  });
}

export function useHome() {
  return useQuery({
    queryKey: ['home'],
    queryFn: () => apiFetch<CurationHome>('/home'),
  });
