id: custom-name-skill
name: Custom Name Display
description: Old metadata desc
collection: default
collection_id: default
status: active
history:
  - occurred_at: "2026-10-04T08:08:00Z"
    state: active
created_at: "2026-10-04T08:08:00Z"
updated_at: "2026-10-04T08:08:00Z"
quality:
  reviewed: true
  curated: false
