	root, err := workspace.Discover(path)
	if err != nil {
		return SkillSourcesResult{}, err
	}

	skillID = strings.TrimSpace(skillID)
	if skillID == "" {
		return SkillSourcesResult{}, skill.ErrNotFound
	}

	_, _, _, err = locateSkillDir(root, skillID)
	if err != nil {
		return SkillSourcesResult{}, skill.ErrNotFound
