	// 1. Get Upstream (nil if skill has no github/git origin)
	var upstream *SkillUpstream
	up, upErr := GetSkillUpstream(ctx, root, skillID)
	if upErr == nil && up.Repository != "" && up.Status != "untracked" {
		upstream = &up
