package migration

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"gopkg.in/yaml.v3"

	"github.com/vantt/mcp-skill-hub/internal/app"
	"github.com/vantt/mcp-skill-hub/internal/mutation"
	"github.com/vantt/mcp-skill-hub/internal/workspace"
)

func TestMigrationV4ToV5_StripsBodiesFromLegacyReceipt(t *testing.T) {
	t.Parallel()

	root := filepath.Join(t.TempDir(), "workspace")
	if _, err := workspace.Apply(root); err != nil {
		t.Fatal(err)
	}
	_ = os.WriteFile(filepath.Join(root, ".skillhub", "schema-version"), []byte("4\n"), 0o644)

	// Copy the live hub's 208 KB receipt fixture
	liveReceiptPath := "/home/vantt/skill-hub/history/operations/2026/10/OP-c011d730fa8122171101881543a63bc8.yaml"
	receiptData, err := os.ReadFile(liveReceiptPath)
	if err != nil {
		t.Skipf("live hub 208 KB receipt fixture not found at %s: %v", liveReceiptPath, err)
	}

	beforeSize := len(receiptData)
	if beforeSize < 100<<10 {
		t.Fatalf("expected large receipt before migration (>100 KB), got %d bytes", beforeSize)
	}

	targetDir := filepath.Join(root, "history", "operations", "2026", "10")
	if err := os.MkdirAll(targetDir, 0o755); err != nil {
		t.Fatal(err)
	}
	targetFile := filepath.Join(targetDir, "OP-c011d730fa8122171101881543a63bc8.yaml")
	if err := os.WriteFile(targetFile, receiptData, 0o644); err != nil {
		t.Fatal(err)
	}

	reg := DefaultRegistry()
	proposal, err := reg.Preview(root, CurrentVersion)
	if err != nil {
		t.Fatalf("preview failed: %v", err)
	}
	if proposal.SourceVersion != 4 || proposal.TargetVersion != 5 {
		t.Fatalf("unexpected versions: source=%d, target=%d", proposal.SourceVersion, proposal.TargetVersion)
	}

	_, err = mutation.ConfirmMutation(root, proposal.Mutation, mutation.Confirmation{
		ProposalID:          proposal.ID,
		ProposalDigest:      proposal.Digest,
		BaseCatalogSnapshot: proposal.BaseSnapshot,
	})
	if err != nil {
		t.Fatalf("confirm failed: %v", err)
	}

	// Verify new schema version is 5
	newVer, err := DetectVersion(root)
	if err != nil || newVer != 5 {
		t.Fatalf("expected schema version 5, got %d, %v", newVer, err)
	}

	// Read migrated receipt
	afterData, err := os.ReadFile(targetFile)
	if err != nil {
		t.Fatalf("read migrated receipt: %v", err)
	}
	afterSize := len(afterData)

	// Verify dramatic shrinkage (>90% reduction, under 10 KB)
	if afterSize > 10<<10 {
		t.Fatalf("expected stripped receipt < 10 KB, got %d bytes (was %d bytes)", afterSize, beforeSize)
	}

	// Unmarshal and assert body fields are completely absent
	var doc struct {
		ID      string `yaml:"id"`
		Changes []map[string]any `yaml:"changes"`
	}
	if err := yaml.Unmarshal(afterData, &doc); err != nil {
		t.Fatalf("unmarshal migrated receipt: %v", err)
	}
	if doc.ID != "OP-c011d730fa8122171101881543a63bc8" {
		t.Fatalf("expected id OP-c011d730fa8122171101881543a63bc8, got %q", doc.ID)
	}
	if len(doc.Changes) == 0 {
		t.Fatal("expected non-empty changes")
	}
	for i, ch := range doc.Changes {
		if _, ok := ch["before_content"]; ok {
			t.Fatalf("change[%d] still has before_content", i)
		}
		if _, ok := ch["after_content"]; ok {
			t.Fatalf("change[%d] still has after_content", i)
		}
		if _, ok := ch["content_available"]; ok {
			t.Fatalf("change[%d] still has content_available", i)
		}
		if _, ok := ch["path"]; !ok {
			t.Fatalf("change[%d] missing path", i)
		}
	}
}

func TestNewReceiptHasNoBodyFields(t *testing.T) {
	t.Parallel()

	root := filepath.Join(t.TempDir(), "workspace")
	if _, err := (app.WorkspaceService{}).Init(root, true); err != nil {
		t.Fatal(err)
	}

	// Apply a mutation via mutation.PlanMutation and ConfirmMutation
	set := mutation.WriteSet{
		Command: "test_cmd",
		Changes: []mutation.Change{
			{Path: "test-file.txt", Contents: []byte("new content for testing\n")},
		},
	}
	planned, err := mutation.PlanMutation(root, set)
	if err != nil {
		t.Fatal(err)
	}
	receipt, err := mutation.ConfirmMutation(root, planned, mutation.Confirmation{
		ProposalID:          planned.ID,
		ProposalDigest:      planned.Digest,
		BaseCatalogSnapshot: planned.BaseCatalogSnapshot,
	})
	if err != nil {
		t.Fatal(err)
	}

	receiptMatches, err := filepath.Glob(filepath.Join(root, "history", "operations", "*", "*", receipt.OperationID+".yaml"))
	if err != nil || len(receiptMatches) != 1 {
		t.Fatalf("expected receipt on disk for %s, got %#v", receipt.OperationID, receiptMatches)
	}

	receiptBytes, err := os.ReadFile(receiptMatches[0])
	if err != nil {
		t.Fatal(err)
	}

	var rawDoc map[string]any
	if err := yaml.Unmarshal(receiptBytes, &rawDoc); err != nil {
		t.Fatal(err)
	}

	changes, ok := rawDoc["changes"].([]any)
	if !ok || len(changes) != 1 {
		t.Fatalf("expected 1 change, got %#v", rawDoc["changes"])
	}

	ch := changes[0].(map[string]any)
	if _, ok := ch["before_content"]; ok {
		t.Fatal("new receipt must not contain before_content")
	}
	if _, ok := ch["after_content"]; ok {
		t.Fatal("new receipt must not contain after_content")
	}
	if _, ok := ch["content_available"]; ok {
		t.Fatal("new receipt must not contain content_available")
	}
	if ch["path"] != "test-file.txt" {
		t.Fatalf("path = %v, want test-file.txt", ch["path"])
	}
}

func TestGetOperationDiff_CommittedMatchesGitDiff(t *testing.T) {
	t.Parallel()

	root := filepath.Join(t.TempDir(), "workspace")
	if _, err := (app.WorkspaceService{}).Init(root, true); err != nil {
		t.Fatal(err)
	}

	// Create and confirm a mutation
	filePath := "hello.txt"
	set := mutation.WriteSet{
		Command: "test_create",
		Changes: []mutation.Change{
			{Path: filePath, Contents: []byte("Line 1: initial content\nLine 2: more content\n")},
		},
	}
	planned, err := mutation.PlanMutation(root, set)
	if err != nil {
		t.Fatal(err)
	}
	receipt, err := mutation.ConfirmMutation(root, planned, mutation.Confirmation{
		ProposalID:          planned.ID,
		ProposalDigest:      planned.Digest,
		BaseCatalogSnapshot: planned.BaseCatalogSnapshot,
	})
	if err != nil {
		t.Fatal(err)
	}

	// Commit the mutation and receipt to Git
	cmdAdd := exec.Command("git", "-C", root, "add", "-A")
	if out, err := cmdAdd.CombinedOutput(); err != nil {
		t.Fatalf("git add: %v (%s)", err, string(out))
	}
	cmdCommit := exec.Command("git", "-C", root, "-c", "user.name=Test", "-c", "user.email=test@example.invalid", "commit", "-m", "apply test_create")
	if out, err := cmdCommit.CombinedOutput(); err != nil {
		t.Fatalf("git commit: %v (%s)", err, string(out))
	}

	// Call GetOperationDiff
	wsSvc := app.WorkspaceService{}
	diffRes, err := wsSvc.GetOperationDiff(context.Background(), root, receipt.OperationID)
	if err != nil {
		t.Fatalf("GetOperationDiff: %v", err)
	}

	if diffRes.OperationID != receipt.OperationID || len(diffRes.Changes) != 1 {
		t.Fatalf("unexpected diffRes: %#v", diffRes)
	}
	ch := diffRes.Changes[0]
	if !ch.DiffAvailable {
		t.Fatal("expected DiffAvailable == true for committed operation")
	}
	if ch.After != "Line 1: initial content\nLine 2: more content\n" {
		t.Fatalf("unexpected after content: %q", ch.After)
	}

	// Verify that diff contains the added lines
	if !strings.Contains(ch.Diff, "+Line 1: initial content") {
		t.Fatalf("diff missing added line: %s", ch.Diff)
	}
}

func TestGetOperationDiff_OldReceiptWithBodiesStillLoads(t *testing.T) {
	t.Parallel()

	root := filepath.Join(t.TempDir(), "workspace")
	if _, err := (app.WorkspaceService{}).Init(root, true); err != nil {
		t.Fatal(err)
	}

	opDir := filepath.Join(root, "history", "operations", "2026", "10")
	if err := os.MkdirAll(opDir, 0o755); err != nil {
		t.Fatal(err)
	}

	oldReceipt := `schema_version: 1
id: op_legacy_bodies
kind: legacy_cmd
occurred_at: "2026-10-09T08:00:00Z"
idempotency_key: key-legacy
request_digest: sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa
status: applied
changes:
  - path: legacy.txt
    before: ""
    after: sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb
    before_content: "Old line\n"
    after_content: "New line\n"
    content_available: true
`
	if err := os.WriteFile(filepath.Join(opDir, "op_legacy_bodies.yaml"), []byte(oldReceipt), 0o644); err != nil {
		t.Fatal(err)
	}

	wsSvc := app.WorkspaceService{}
	diffRes, err := wsSvc.GetOperationDiff(context.Background(), root, "op_legacy_bodies")
	if err != nil {
		t.Fatalf("GetOperationDiff on legacy receipt: %v", err)
	}

	if len(diffRes.Changes) != 1 {
		t.Fatalf("expected 1 change, got %d", len(diffRes.Changes))
	}
	ch := diffRes.Changes[0]
	if !ch.DiffAvailable {
		t.Fatal("expected DiffAvailable == true for legacy receipt with bodies")
	}
	if ch.Before != "Old line\n" || ch.After != "New line\n" {
		t.Fatalf("before/after mismatch: before=%q, after=%q", ch.Before, ch.After)
	}
}

