	// Step 2: Verify all 3 skills in v3 match their v1 baselines completely
	for _, id := range skillIDs {
		review, err := service.ReviewSkill(ctx, root, id)
		if err != nil {
			t.Fatalf("ReviewSkill(%s) in v3: %v", id, err)
		}
