	scratch := t.TempDir()
	hub := scratch + "/hub"
	cmd := exec.Command("git", "clone", "/home/vantt/skill-hub", hub)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("clone: %v (%s)", err, string(out))
	}
	t.Setenv("XDG_DATA_HOME", scratch+"/data")
	t.Setenv("XDG_CONFIG_HOME", scratch+"/config")
	t.Setenv("XDG_CACHE_HOME", scratch+"/cache")

	mig := MigrationService{}
	applied, err := mig.Migrate(context.Background(), hub, 5, true)
	if err != nil {
		t.Fatalf("migrate: %v", err)
	}
	t.Logf("migration status: %s", applied.Status)

	cmdAdd := exec.Command("git", "-C", hub, "add", "-A")
	_ = cmdAdd.Run()
	cmdCommit := exec.Command("git", "-C", hub, "-c", "user.name=Test", "-c", "user.email=test@example.invalid", "commit", "-m", "apply v5 migration")
	_ = cmdCommit.Run()

	ws := WorkspaceService{}
	for _, opID := range []string{"OP-02e11071f24379a54a8a1c4b15a08066", "OP-c011d730fa8122171101881543a63bc8"} {
		res, err := ws.GetOperationDiff(context.Background(), hub, opID)
		if err != nil {
			t.Fatalf("diff %s: %v", opID, err)
		}
		data, _ := json.MarshalIndent(res, "", "  ")
		fmt.Printf("\n=== RESULT %s ===\n%s\n", opID, string(data))
	}
}
EOF

